package com.r2h.sirr.core

/** Canonical stories are generated from content/whispers_scratch_stories_v1.json. */
internal enum class SecretTier(val arabic: String) {
    SOFT("هادي"), FLIRT("غزل"), ADULT("حميم 18+")
}

internal data class SecretStory(val id: String, val tier: SecretTier, val lines: List<String>) {
    init {
        require(id.matches(Regex("[ws][0-9]{2}")))
        require(lines.size == 3 && lines.all { it.isNotBlank() && it.length <= 350 })
    }
}

